IF DB_ID(N'QuanLyCongTyDuLich') IS NULL CREATE DATABASE QuanLyCongTyDuLich;
GO
USE QuanLyCongTyDuLich;
GO
-- Re-runnable for new installations. Do not drop tables in an existing populated database.
IF OBJECT_ID('dbo.Tour','U') IS NULL CREATE TABLE dbo.Tour (MaTour INT IDENTITY PRIMARY KEY,TenTour NVARCHAR(200) NOT NULL,SoNgay INT NOT NULL CHECK(SoNgay>0),SoDem INT NOT NULL CHECK(SoDem>=0),DonGia DECIMAL(18,2) NOT NULL CHECK(DonGia>0));
IF OBJECT_ID('dbo.ChuyenDi','U') IS NULL CREATE TABLE dbo.ChuyenDi (MaChuyen INT IDENTITY PRIMARY KEY,MaTour INT NOT NULL REFERENCES dbo.Tour(MaTour),NgayDi DATE NOT NULL,NgayVe DATE NOT NULL,SoCho INT NOT NULL CHECK(SoCho>0),CONSTRAINT CK_ChuyenDi_Ngay CHECK(NgayVe>=NgayDi));
IF OBJECT_ID('dbo.KhachHang','U') IS NULL CREATE TABLE dbo.KhachHang (MaKH INT IDENTITY PRIMARY KEY,TenKH NVARCHAR(150) NOT NULL,DiaChi NVARCHAR(300) NULL,DienThoai NVARCHAR(20) NULL);
IF OBJECT_ID('dbo.NhanVienHDDL','U') IS NULL CREATE TABLE dbo.NhanVienHDDL (MaNV INT IDENTITY PRIMARY KEY,TenNV NVARCHAR(150) NOT NULL,LuongCB DECIMAL(18,2) NOT NULL CHECK(LuongCB>=0));
IF OBJECT_ID('dbo.DiemThamQuan','U') IS NULL CREATE TABLE dbo.DiemThamQuan (MaDiem INT IDENTITY PRIMARY KEY,TenDiem NVARCHAR(200) NOT NULL,DiaDiem NVARCHAR(250) NULL,NoiDung NVARCHAR(MAX) NULL,YNghia NVARCHAR(MAX) NULL);
IF OBJECT_ID('dbo.NoiDungChan','U') IS NULL CREATE TABLE dbo.NoiDungChan (MaNoiDC INT IDENTITY PRIMARY KEY,MaTour INT NOT NULL REFERENCES dbo.Tour(MaTour),ThuTu INT NOT NULL CHECK(ThuTu>0),TenNoi NVARCHAR(200) NOT NULL,CoDoiPhuongTien BIT NOT NULL DEFAULT 0,CoNoiAn BIT NOT NULL DEFAULT 0,CoKhachSan BIT NOT NULL DEFAULT 0,LoaiKhachSan INT NULL,CONSTRAINT CK_NDC_Stars CHECK ((CoKhachSan=0 AND LoaiKhachSan IS NULL) OR (CoKhachSan=1 AND LoaiKhachSan BETWEEN 2 AND 5)),CONSTRAINT UQ_NDC UNIQUE(MaTour,ThuTu));
IF OBJECT_ID('dbo.TourDiemThamQuan','U') IS NULL CREATE TABLE dbo.TourDiemThamQuan (MaTourDiem INT IDENTITY PRIMARY KEY,MaTour INT NOT NULL REFERENCES dbo.Tour(MaTour),MaDiem INT NOT NULL REFERENCES dbo.DiemThamQuan(MaDiem),ThuTu INT NOT NULL CHECK(ThuTu>0),CONSTRAINT UQ_TourDiem UNIQUE(MaTour,MaDiem));
IF OBJECT_ID('dbo.TourChang','U') IS NULL CREATE TABLE dbo.TourChang (MaChang INT IDENTITY PRIMARY KEY,MaTour INT NOT NULL REFERENCES dbo.Tour(MaTour),ThuTu INT NOT NULL CHECK(ThuTu>0),NoiDi NVARCHAR(200) NOT NULL,NoiDen NVARCHAR(200) NOT NULL,PhuongTien NVARCHAR(100) NOT NULL,CONSTRAINT UQ_TourChang UNIQUE(MaTour,ThuTu));
IF OBJECT_ID('dbo.PhieuDangKy','U') IS NULL CREATE TABLE dbo.PhieuDangKy (MaPhieu INT IDENTITY PRIMARY KEY,MaKH INT NOT NULL REFERENCES dbo.KhachHang(MaKH),MaTour INT NOT NULL REFERENCES dbo.Tour(MaTour),MaChuyen INT NULL REFERENCES dbo.ChuyenDi(MaChuyen),LoaiDangKy VARCHAR(4) NOT NULL CHECK(LoaiDangKy IN ('LE','DOAN')),SoNguoi INT NOT NULL CHECK(SoNguoi>0),NgayLap DATETIME2 NOT NULL DEFAULT SYSDATETIME(),NgayDi DATE NOT NULL,TongTien DECIMAL(18,2) NOT NULL CHECK(TongTien>0),TrangThai VARCHAR(20) NOT NULL DEFAULT 'DA_XAC_NHAN' CHECK (TrangThai IN ('DA_XAC_NHAN','HUY','HOAN_THANH')),CoBaoHiem BIT NOT NULL DEFAULT 0,CONSTRAINT CK_Phieu_PhanLoai CHECK((LoaiDangKy='LE' AND SoNguoi BETWEEN 1 AND 11 AND MaChuyen IS NOT NULL) OR (LoaiDangKy='DOAN' AND SoNguoi>=12 AND MaChuyen IS NULL)));
IF OBJECT_ID('dbo.KhachDoan','U') IS NULL CREATE TABLE dbo.KhachDoan (MaPhieu INT PRIMARY KEY REFERENCES dbo.PhieuDangKy(MaPhieu),TenCoQuan NVARCHAR(200) NOT NULL,NguoiDaiDien NVARCHAR(150) NOT NULL,DiaDiemDon NVARCHAR(250) NOT NULL,DienThoai NVARCHAR(20) NULL);
IF OBJECT_ID('dbo.NguoiDuLich','U') IS NULL CREATE TABLE dbo.NguoiDuLich (MaNguoi INT IDENTITY PRIMARY KEY,MaPhieu INT NOT NULL REFERENCES dbo.PhieuDangKy(MaPhieu),HoTen NVARCHAR(150) NOT NULL,NgaySinh DATE NULL,SoGiayTo NVARCHAR(30) NULL);
IF OBJECT_ID('dbo.ThanhToan','U') IS NULL CREATE TABLE dbo.ThanhToan (MaThanhToan INT IDENTITY PRIMARY KEY,MaPhieu INT NOT NULL REFERENCES dbo.PhieuDangKy(MaPhieu),LoaiThanhToan VARCHAR(12) NOT NULL CHECK(LoaiThanhToan IN ('COC','VE','QUYET_TOAN','HOAN_TIEN')),SoTien DECIMAL(18,2) NOT NULL CHECK(SoTien>0),NgayThanhToan DATETIME2 NOT NULL DEFAULT SYSDATETIME());
IF OBJECT_ID('dbo.PhanCong','U') IS NULL CREATE TABLE dbo.PhanCong (MaPhanCong INT IDENTITY PRIMARY KEY,MaNV INT NOT NULL REFERENCES dbo.NhanVienHDDL(MaNV),MaPhieu INT NOT NULL REFERENCES dbo.PhieuDangKy(MaPhieu),LuongTour DECIMAL(18,2) NOT NULL CHECK(LuongTour>=0),CONSTRAINT UQ_PhanCong UNIQUE(MaNV,MaPhieu));
IF OBJECT_ID('dbo.PhieuKhaoSat','U') IS NULL CREATE TABLE dbo.PhieuKhaoSat (MaPhieuKS INT IDENTITY PRIMARY KEY,MaPhieu INT NOT NULL REFERENCES dbo.PhieuDangKy(MaPhieu),NoiDungGopY NVARCHAR(MAX) NULL,DiemDanhGia INT NOT NULL CHECK(DiemDanhGia BETWEEN 1 AND 5),NgayKhaoSat DATETIME2 NOT NULL DEFAULT SYSDATETIME(),CONSTRAINT UQ_KhaoSat UNIQUE(MaPhieu));
GO
CREATE OR ALTER VIEW dbo.v_CongNoDoan AS
SELECT p.MaPhieu,p.TongTien,ISNULL(SUM(CASE WHEN tt.LoaiThanhToan='HOAN_TIEN' THEN -tt.SoTien ELSE tt.SoTien END),0) AS DaThu,p.TongTien-ISNULL(SUM(CASE WHEN tt.LoaiThanhToan='HOAN_TIEN' THEN -tt.SoTien ELSE tt.SoTien END),0) AS ConLai
FROM dbo.PhieuDangKy p LEFT JOIN dbo.ThanhToan tt ON p.MaPhieu=tt.MaPhieu WHERE p.LoaiDangKy='DOAN' GROUP BY p.MaPhieu,p.TongTien;
GO
